package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicFractionComparisonOrderTest {
 @Test public void everySelectedYearFiveComparisonUsesPublicCrossProducts(){int count=0;Set<String> signs=new HashSet<>();for(int b=2;b<=12;b++)for(int d=2;d<=12;d++){if(b==d||java.math.BigInteger.valueOf(b).gcd(java.math.BigInteger.valueOf(d)).intValue()<2)continue;for(int a=1;a<=b;a++)for(int c=1;c<=d;c++){int cmp=Integer.compare(a*d,c*b);String expected=cmp<0?"<":cmp>0?">":"=";signs.add(expected);Question q=new Question("el_fraction_compare",a+"/"+b+"  □  "+c+"/"+d,"poison","poison");q.kind="symbol";assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());for(String wrong:List.of("<",">","="))if(!wrong.equals(expected))assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(wrong)).status);count++;}}assertTrue(count>100);assertEquals(Set.of("<","=",">"),signs);System.out.println("Year5 public comparison conditions="+count);}
 @Test public void existingYearFiveTypesSupplyHundredFreshAndKeysDoNotControlOrder(){var pack=GlobalCurriculum.packs("GB").stream().filter(p->p.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:List.of("el_fraction_compare","fractionOrder")){assertTrue(pack.inGrade(id,5));Generator gen=new Generator(new Random(175));List<String> recent=new ArrayList<>();boolean ascending=false,descending=false;for(int i=0;i<100;i++){Question q=gen.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,5));assertFalse(recent.contains(q.signature()));recent.add(q.signature());List<String> expected;if(id.equals("fractionOrder")){expected=new ArrayList<>(FractionOrdering.givens(q));boolean reverse=q.prompt.startsWith("큰");ascending|=!reverse;descending|=reverse;expected.sort((a,b)->Expression.number(a).compareTo(Expression.number(b))*(reverse?-1:1));}else{String[] v=q.prompt.split("\\s+□\\s+");int cmp=Expression.number(v[0]).compareTo(Expression.number(v[1]));expected=List.of(cmp<0?"<":cmp>0?">":"=");}q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),expected).correct());HelpPlan plan=HelpPlan.forQuestion(q);assertNotNull(plan);assertFalse(plan.canTransfer());if(id.equals("fractionOrder")){for(int n=0;n<3;n++){List<String> wrong=new ArrayList<>(expected);Collections.swap(wrong,n,(n+1)%3);assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),wrong).status);}}}if(id.equals("fractionOrder"))assertTrue(ascending&&descending);}}
 @Test public void invalidOperandsMissingOrRepeatedCardsDoNotPass(){for(String prompt:List.of("1/0  □  1/2","1/2  □  1/0","9999999/2  □  1/2","not a comparison")){Question q=new Question("el_fraction_compare",prompt,"","=");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("=")).status);}Question q=new Question("fractionOrder","작은 분수부터 고르세요.\n1/2 · 1/4 · 1/8","poison","poison");assertTrue(new Checker().check(q,List.of(),List.of("1/8","1/4","1/2")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1/8","","1/2")).status);assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of("1/8","1/8","1/2")).status);q.prompt="작은 분수부터 고르세요.\n1/2 · 2/4 · 1/8";assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1/8","1/2","2/4")).status);}
 @Test public void relatedDecimalAndSameDenominatorFlowsRemainPublic(){for(String id:List.of("fracCompare","el_decimal_compare")){Question q=new Question(id,id.equals("fracCompare")?"1/4  □  2/4":"1.20  □  1.2","poison","wrong");assertTrue(new Checker().check(q,List.of(),List.of(id.equals("fracCompare")?"<":"=")).correct());}Question q=new Question("decimalOrder","큰 소수부터 고르세요.\n0.01 · 0.001 · 0.1","poison","wrong");assertTrue(new Checker().check(q,List.of(),List.of("0.1","0.01","0.001")).correct());}
}
